pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address[] memory _tos, uint256[] memory v) public {
        vm.assume(_tos.length > 0 && _tos.length == v.length);
        vm.assume(address(this) != 0x9797055B68C5DadDE6b3c7d5D80C9CFE2eecE6c9); // not the from address
        // We need to impersonate the from address to call transfer
        vm.startPrank(0x9797055B68C5DadDE6b3c7d5D80C9CFE2eecE6c9);

        uint256 balanceBefore = address(c).balance;

        // Compute expected total ether sent (in wei) for the REFERENCE (scaled by 1e18)
        uint256 expectedTotalWei = 0;
        for (uint256 i = 0; i < v.length; i++) {
            expectedTotalWei += v[i] * 1000000000000000000; // 1 ether = 1e18 wei
        }

        // Ensure the contract has enough ether to send (simulate by minting)
        vm.deal(address(c), expectedTotalWei);

        bool success = c.transfer(_tos, v);

        vm.stopPrank();

        uint256 balanceAfter = address(c).balance;

        // The rule: the contract's balance decreased exactly by the sum of scaled amounts
        assertTrue(success && balanceBefore - balanceAfter == expectedTotalWei);
    }
}

