import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address[] memory tos, uint256[] memory v) public {
        vm.assume(tos.length == v.length);
        vm.assume(tos.length > 0);
        vm.prank(0x9797055B68C5DadDE6b3c7d5D80C9CFE2eecE6c9);
        address fromBefore = c.from();
        (bool success, ) = address(c).call(abi.encodeWithSelector(c.transfer.selector, tos, v));
        if (success) {
            assertTrue(c.from() == fromBefore);
        }
    }
}

