pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address[] calldata tos, uint[] calldata v) public {
        // Bound v values to avoid overflow issues
        vm.assume(tos.length == v.length);
        // Only call from authorized sender
        vm.prank(0x9797055B68C5DadDE6b3c7d5D80C9CFE2eecE6c9);
        bool success;
        if (tos.length == 0) {
            (success,) = address(c).call(abi.encodeWithSelector(c.transfer.selector, tos, v));
            // Reference C should revert on empty array
            assertTrue(!success, "Reference should revert on empty array");
        } else {
            // For non-empty arrays, both should succeed
            (success,) = address(c).call(abi.encodeWithSelector(c.transfer.selector, tos, v));
            assertTrue(success, "Non-empty arrays should not revert");
        }
    }
}

